// gatewayPolicyError identifies a refusal generated by the gateway rather than its upstream agent.
type gatewayPolicyError string

// Error returns the policy refusal without changing its user-facing message.
func (e gatewayPolicyError) Error() string { return string(e) }

type publicTargetsOnlyKey struct{}

// WithPublicTargetsOnly prevents an unauthenticated administrative operation
// from using the operator's private-network permissions.
func WithPublicTargetsOnly(ctx context.Context, required bool) context.Context {
	return context.WithValue(ctx, publicTargetsOnlyKey{}, required)
}

// requiresPublicTargets reads the server-owned destination policy.
func requiresPublicTargets(ctx context.Context) bool {
	required, _ := ctx.Value(publicTargetsOnlyKey{}).(bool)
	return required
}

type outboundPolicy struct {
	dial          *network.DialPolicy
	fingerprint   [sha256.Size]byte
	requirePublic bool
}

// outboundPolicy snapshots operator permissions so each connection pool has a
// single immutable policy. Invalid settings fail closed rather than permitting
// private connections.
func (m *Manager) outboundPolicy(ctx context.Context) (outboundPolicy, error) {
	requirePublic := requiresPublicTargets(ctx)
	var entries []string
	if !requirePublic && m.privateAllowlistFn != nil {
		entries = slices.Clone(m.privateAllowlistFn())
	}
	slices.Sort(entries)
	allow, err := network.ValidatePrivateTargetAllowlist(entries)
	if err != nil {
		return outboundPolicy{}, gatewayPolicyError("invalid Agent Gateway private network allowlist")
	}
	resolve := func(ctx context.Context, host string) ([]net.IP, error) {
		ips, err := network.ResolveAllowlistedPrivateTarget(ctx, host, allow)
		return ips, agentDestinationError(err, requirePublic)
	}
	dialTarget := network.AllowlistedPrivateDialContext(10*time.Second, func() *network.Allowlist { return allow })
	dial := func(ctx context.Context, netw, addr string) (net.Conn, error) {
		conn, err := dialTarget(ctx, netw, addr)
		return conn, agentDestinationError(err, requirePublic)
	}
	return outboundPolicy{
		dial:        network.NewDialPolicy(dial, resolve),
		fingerprint: sha256.Sum256([]byte(strings.Join(entries, "\x00"))), requirePublic: requirePublic,
	}, nil
}

// agentDestinationError adds configuration guidance only for destinations that can be allowlisted.
func agentDestinationError(err error, requirePublic bool) error {
	var blocked *network.PrivateTargetNotAllowedError
	if !errors.As(err, &blocked) {
		return err
	}
	if requirePublic {
		return fmt.Errorf("%w; private Agent Gateway destinations require an authenticated admin session", err)
	}
	return fmt.Errorf("%w; to allow this destination, add its host, IP, or CIDR to the Private Network Allowlist in Agent Settings, client.a2a_private_allowlist in config.json, or bifrost.client.a2aPrivateAllowlist in Helm values", err)
}

// policyCurrent refuses new work on pools approved under superseded permissions.
func (m *Manager) policyCurrent(policy outboundPolicy) bool {
	var entries []string
	if !policy.requirePublic && m.privateAllowlistFn != nil {
		entries = slices.Clone(m.privateAllowlistFn())
	}
	slices.Sort(entries)
	return sha256.Sum256([]byte(strings.Join(entries, "\x00"))) == policy.fingerprint
}

// configureOutboundTransport preserves TLS while guarding both direct and proxy
// connections. Proxy tunnels use a checked IP, preserving TLS SNI and HTTP Host.
func (m *Manager) configureOutboundTransport(tr *http.Transport, policy outboundPolicy) http.RoundTripper {
	proxy := tr.Proxy
	if m.httpClient.Transport == nil {
		proxy = network.DefaultProxyFunc(network.ClientPurposeAPI)
	}
	tr.Proxy = nil
	tr.DialTLSContext = nil
	tr.DialTLS = nil
	tr.DialContext = func(ctx context.Context, netw, addr string) (net.Conn, error) {
		return policy.dial.DialContext(ctx, netw, addr, nil)
	}
	return &outboundHTTPTransport{direct: tr, proxy: proxy, policy: policy}
}

// outboundHTTPTransport keeps direct and proxied pools separate. It retains at
// most one proxy pool, replacing it when operator proxy configuration changes.
type outboundHTTPTransport struct {
	direct   *http.Transport
	proxy    func(*http.Request) (*url.URL, error)
	policy   outboundPolicy
	mu       sync.Mutex
	proxyURL string
	proxied  *http.Transport
}

// RoundTrip selects the proxy from the actual request, including its scheme,
// then tunnels to a checked destination IP without asking the proxy to resolve it.
func (t *outboundHTTPTransport) RoundTrip(req *http.Request) (*http.Response, error) {
	var proxyURL *url.URL
	if t.proxy != nil {
		var err error
		proxyURL, err = t.proxy(req)
		if err != nil {
			return nil, err
		}
	}
	if proxyURL == nil {
		return t.direct.RoundTrip(req)
	}
	t.mu.Lock()
	if t.proxied == nil || t.proxyURL != proxyURL.String() {
		if t.proxied != nil {
			t.proxied.CloseIdleConnections()
		}
		tr := t.direct.Clone()
		tr.DialContext = func(ctx context.Context, netw, addr string) (net.Conn, error) {
			return t.policy.dial.DialContext(ctx, netw, addr, proxyURL)
		}
		t.proxied, t.proxyURL = tr, proxyURL.String()
	}
	tr := t.proxied
	t.mu.Unlock()
	return tr.RoundTrip(req)
}

// CloseIdleConnections releases both pools without disrupting in-flight calls.
func (t *outboundHTTPTransport) CloseIdleConnections() {
	t.direct.CloseIdleConnections()
	t.mu.Lock()
	defer t.mu.Unlock()
	if t.proxied != nil {
		t.proxied.CloseIdleConnections()
	}
}

// ValidateCredentialOrigins checks additional runtime credential destinations.
// An origin identifies a service, so paths, credentials and query components
// are forbidden. The returned values are canonical and independently owned.
func ValidateCredentialOrigins(values []string) ([]string, error) {
	if len(values) > 32 {
		return nil, errors.New("credential_origins cannot contain more than 32 entries")
	}
	result := make([]string, 0, len(values))
	for _, value := range values {
		u, err := validatedHTTPURL(value)
		if err != nil || u.Path != "" || u.RawQuery != "" || u.ForceQuery || u.Fragment != "" || u.RawFragment != "" || strings.ContainsAny(value, "?#") {
			return nil, errors.New("credential_origins must be HTTP(S) origins without paths, userinfo, queries, or fragments")
		}
		result = append(result, canonicalOrigin(u))
	}
	slices.Sort(result)
	return slices.Compact(result), nil
}

// canonicalOrigin normalizes the default port and case without changing service identity.
func canonicalOrigin(u *url.URL) string {
	host := strings.ToLower(u.Hostname())
	port := u.Port()
	if port == "" || (u.Scheme == "https" && port == "443") || (u.Scheme == "http" && port == "80") {
		if strings.Contains(host, ":") {
			host = "[" + host + "]"
		}
	} else {
		host = net.JoinHostPort(host, port)
	}
	return strings.ToLower(u.Scheme) + "://" + host
}

// permitsCredentialOrigin binds runtime credentials to the card's origin or an
// explicit operator-approved additional origin.
func permitsCredentialOrigin(cardURL string, origins []string, target *url.URL) bool {
	card, err := validatedHTTPURL(cardURL)
	return err == nil && (canonicalOrigin(card) == canonicalOrigin(target) || slices.Contains(origins, canonicalOrigin(target)))
}

// runtimeInterfaceURL represents bare gRPC targets as HTTPS origins, matching
// grpcUpstreamTarget's default TLS behavior.
func runtimeInterfaceURL(raw string) (*url.URL, error) {
	if !strings.Contains(raw, "://") {
		raw = "https://" + raw
	}
	return validatedHTTPURL(raw)
}

// CloseIdleConnections releases sockets retained by a credentialed transport.
func (t *credentialTransport) CloseIdleConnections() {
	if closer, ok := t.base.(interface{ CloseIdleConnections() }); ok {
		closer.CloseIdleConnections()
	}
}
